CREATE OR REPLACE FUNCTION public.fic_escalate_atms_alert(p_alert_id uuid, p_report_type text, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'fic', 'pg_temp'
AS $function$
DECLARE
  v_customer_id BIGINT;
  v_org_id      UUID;
  v_report_id   UUID;
BEGIN
  PERFORM public.assert_org_admin();
  SELECT ca.customer_id, ca.org_id
  INTO   v_customer_id, v_org_id
  FROM   fic.compliance_alerts ca
  WHERE  ca.alert_id = p_alert_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Alert % not found', p_alert_id;
  END IF;

  INSERT INTO fic.regulatory_reports (
    org_id, customer_id, report_type, status,
    reason_for_reporting, compliance_alert_id, created_by
  ) VALUES (
    v_org_id, v_customer_id, p_report_type, 'draft',
    p_reason, p_alert_id, 'compliance_ui'
  ) RETURNING report_id INTO v_report_id;

  UPDATE fic.compliance_alerts
  SET    status               = 'escalated',
         reviewed_at          = NOW(),
         review_notes         = 'Escalated to ' || p_report_type || ' report: ' || p_reason,
         regulatory_report_id = v_report_id
  WHERE  alert_id = p_alert_id;

  RETURN v_report_id;
END;
$function$
;

