CREATE OR REPLACE FUNCTION public.fic_update_report_status(p_report_id uuid, p_status text, p_fic_ref text DEFAULT NULL::text, p_notes text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'fic', 'pg_temp'
AS $function$
BEGIN
  PERFORM public.assert_org_admin();
  UPDATE fic.regulatory_reports
  SET
    status         = p_status,
    fic_ref_number = COALESCE(p_fic_ref, fic_ref_number),
    notes          = COALESCE(p_notes, notes),
    approved_at    = CASE WHEN p_status = 'approved'  THEN NOW() ELSE approved_at  END,
    approved_by    = CASE WHEN p_status = 'approved'  THEN 'compliance_officer' ELSE approved_by END,
    submitted_at   = CASE WHEN p_status = 'submitted' THEN NOW() ELSE submitted_at END,
    submitted_by   = CASE WHEN p_status = 'submitted' THEN 'compliance_officer' ELSE submitted_by END
  WHERE report_id = p_report_id;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.finova_reinvite_kyc(p_customer_id bigint, p_admin_email text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM public.assert_org_admin();
  IF NOT EXISTS (SELECT 1 FROM public.customer_details WHERE customer_id = p_customer_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Customer not found');
  END IF;

  UPDATE public.kyc_finova
     SET finova_status          = 'invited',
         invited_at             = now(),
         rejected_at            = NULL,
         rejected_by            = NULL,
         rejection_reason       = NULL,
         register_email_sent_at = NULL,
         updated_at             = now()
   WHERE customer_id = p_customer_id;

  IF NOT FOUND THEN
    INSERT INTO public.kyc_finova (customer_id, org_id, finova_status, invited_at)
    SELECT p_customer_id, cd.org_id, 'invited', now()
    FROM public.customer_details cd WHERE cd.customer_id = p_customer_id;
  END IF;

  UPDATE public.customer_details
     SET registration_status = 'kyc'
   WHERE customer_id = p_customer_id;

  RETURN jsonb_build_object('success', true, 'customer_id', p_customer_id, 'status', 'invited');
END;
$function$
;
CREATE OR REPLACE FUNCTION public.finova_reject_kyc(p_customer_id bigint, p_reason text DEFAULT NULL::text, p_admin_email text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM public.assert_org_admin();
  IF NOT EXISTS (SELECT 1 FROM public.customer_details WHERE customer_id = p_customer_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Customer not found');
  END IF;

  UPDATE public.kyc_finova
     SET finova_status    = 'rejected',
         rejected_at      = now(),
         rejected_by      = p_admin_email,
         rejection_reason = p_reason,
         updated_at       = now()
   WHERE customer_id = p_customer_id;

  IF NOT FOUND THEN
    INSERT INTO public.kyc_finova (customer_id, org_id, finova_status, rejected_at, rejected_by, rejection_reason)
    SELECT p_customer_id, cd.org_id, 'rejected', now(), p_admin_email, p_reason
    FROM public.customer_details cd WHERE cd.customer_id = p_customer_id;
  END IF;

  UPDATE public.customer_details
     SET registration_status = 'inactive',
         customer_status      = 'Inactive'
   WHERE customer_id = p_customer_id;

  RETURN jsonb_build_object('success', true, 'customer_id', p_customer_id, 'status', 'rejected');
END;
$function$
;
CREATE OR REPLACE FUNCTION public.get_admin_dashboard_metrics()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_org_id UUID;
  v_result JSONB;
  v_total_customers INT;
  v_active_customers INT;
  v_total_aum NUMERIC;
  v_avg_nav NUMERIC;
  v_alert_critical INT;
  v_alert_error INT;
  v_alert_warn INT;
BEGIN
  PERFORM public.assert_org_admin();
  BEGIN
    v_org_id := current_setting('app.settings.org_id', false)::UUID;
  EXCEPTION WHEN OTHERS THEN
    v_org_id := NULL;
  END;

  SELECT COUNT(*)
  INTO v_total_customers
  FROM public.customer_details
  WHERE v_org_id IS NULL OR org_id = v_org_id;

  SELECT COUNT(*)
  INTO v_active_customers
  FROM public.customer_details
  WHERE (v_org_id IS NULL OR org_id = v_org_id)
    AND registration_status = 'active';

  SELECT COALESCE(SUM(nav_usd), 0)
  INTO v_total_aum
  FROM (
    SELECT DISTINCT ON (b.customer_id)
      b.nav_usd
    FROM lth_pvr.balances_daily b
    INNER JOIN public.customer_details cd ON cd.customer_id = b.customer_id
    WHERE (v_org_id IS NULL OR cd.org_id = v_org_id)
      AND cd.registration_status = 'active'
    ORDER BY b.customer_id, b.date DESC
  ) latest_navs;

  IF v_active_customers > 0 THEN
    v_avg_nav := v_total_aum / v_active_customers;
  ELSE
    v_avg_nav := 0;
  END IF;

  SELECT
    COUNT(*) FILTER (WHERE severity = 'critical') AS critical,
    COUNT(*) FILTER (WHERE severity = 'error')    AS error,
    COUNT(*) FILTER (WHERE severity = 'warn')     AS warn
  INTO v_alert_critical, v_alert_error, v_alert_warn
  FROM public.alert_events
  WHERE (v_org_id IS NULL OR org_id = v_org_id)
    AND created_at >= NOW() - INTERVAL '7 days'
    AND resolved_at IS NULL;

  v_result := jsonb_build_object(
    'total_customers',  v_total_customers,
    'active_customers', v_active_customers,
    'total_aum_usd',    ROUND(v_total_aum, 2),
    'avg_nav_usd',      ROUND(v_avg_nav, 2),
    'alerts', jsonb_build_object(
      'critical', COALESCE(v_alert_critical, 0),
      'error',    COALESCE(v_alert_error, 0),
      'warn',     COALESCE(v_alert_warn, 0)
    ),
    'updated_at', NOW()
  );

  RETURN v_result;
END;
$function$
;

