CREATE OR REPLACE FUNCTION public.get_customer_accrued_fees(p_customer_id bigint)
 RETURNS TABLE(platform_fee_usdt numeric, platform_fee_btc numeric, performance_fee_usdt numeric, management_fee_usdt numeric, fee_schedule text)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_platform_schedule      TEXT;
  v_perf_rate              NUMERIC;
  v_nav                    NUMERIC;
  v_cost_basis             NUMERIC;
  v_hwm_usd                NUMERIC;
  v_hwm_contrib            NUMERIC;
  v_cost_basis_at_last_fee NUMERIC;
  v_last_perf_fee_month    TEXT;
  v_threshold              NUMERIC;
  v_perf_fee_onthefly      NUMERIC;
  v_perf_fee_stored        NUMERIC;
  v_plat_fee_usdt          NUMERIC;
  v_plat_fee_btc           NUMERIC;
  v_mgmt_fee_usdt          NUMERIC;
BEGIN
  PERFORM public.assert_customer_access(p_customer_id::bigint);
  SELECT cs.platform_fee_schedule, cs.performance_fee_rate
    INTO v_platform_schedule, v_perf_rate
  FROM public.customer_strategies cs
  WHERE cs.customer_id = p_customer_id AND cs.status = 'active'
  LIMIT 1;

  SELECT COALESCE(bd.nav_usd, 0), COALESCE(bd.cost_basis_usd, 0)
    INTO v_nav, v_cost_basis
  FROM lth_pvr.balances_daily bd
  WHERE bd.customer_id = p_customer_id
  ORDER BY bd.date DESC LIMIT 1;

  SELECT csd.high_water_mark_usd, csd.hwm_contrib_net_cum,
         csd.cost_basis_at_last_fee, csd.last_perf_fee_month::text
    INTO v_hwm_usd, v_hwm_contrib, v_cost_basis_at_last_fee, v_last_perf_fee_month
  FROM lth_pvr.customer_state_daily csd
  WHERE csd.customer_id = p_customer_id
  ORDER BY csd.date DESC LIMIT 1;

  IF v_last_perf_fee_month IS NULL THEN
    v_threshold := COALESCE(v_cost_basis, 0);
  ELSE
    v_threshold := COALESCE(v_hwm_usd, 0) + COALESCE(v_hwm_contrib, 0)
               + GREATEST(0, COALESCE(v_cost_basis, 0) - COALESCE(v_cost_basis_at_last_fee, v_cost_basis, 0));
  END IF;

  v_perf_fee_onthefly := GREATEST(0, COALESCE(v_nav, 0) - v_threshold) * COALESCE(v_perf_rate, 0);

  IF v_platform_schedule = 'annual' THEN
    SELECT COALESCE(SUM(afa.accrued_platform_fee_usdt), 0),
           COALESCE(SUM(afa.accrued_platform_fee_btc),  0),
           COALESCE(SUM(afa.accrued_performance_fee_usdt), 0)
      INTO v_plat_fee_usdt, v_plat_fee_btc, v_perf_fee_stored
    FROM lth_pvr.annual_fee_accrual afa
    WHERE afa.customer_id = p_customer_id AND afa.settled_at IS NULL;
    IF v_perf_fee_stored > 0 THEN v_perf_fee_onthefly := v_perf_fee_stored; END IF;
  ELSE
    SELECT COALESCE(caf.accumulated_usdt, 0), COALESCE(caf.accumulated_btc, 0)
      INTO v_plat_fee_usdt, v_plat_fee_btc
    FROM lth_pvr.customer_accumulated_fees caf
    WHERE caf.customer_id = p_customer_id;
  END IF;

  -- Accrued management fee (quarterly/annual management schedules) — unsettled periods.
  SELECT COALESCE(SUM(afa.accrued_management_fee_usdt), 0) INTO v_mgmt_fee_usdt
  FROM lth_pvr.annual_fee_accrual afa
  WHERE afa.customer_id = p_customer_id AND afa.settled_at IS NULL;

  RETURN QUERY
  SELECT v_plat_fee_usdt, v_plat_fee_btc, v_perf_fee_onthefly, COALESCE(v_mgmt_fee_usdt, 0),
         COALESCE(v_platform_schedule, 'immediate')::text;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.get_customer_dashboard(p_portfolio_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_result JSONB;
  v_latest_balance RECORD;
  v_total_contributions NUMERIC;
  v_customer_id UUID;
BEGIN
  PERFORM public.assert_org_admin();
  SELECT customer_id INTO v_customer_id
  FROM public.customer_portfolios
  WHERE portfolio_id = p_portfolio_id;

  IF v_customer_id IS NULL THEN
    RETURN jsonb_build_object('error', 'Portfolio not found');
  END IF;

  SELECT
    btc_balance,
    usdt_balance,
    usdpc_balance,
    usdpc_price_usd,
    nav_usd,
    roi_pct,
    cagr_pct,
    balance_date
  INTO v_latest_balance
  FROM lth_pvr.balances_daily
  WHERE portfolio_id = p_portfolio_id
  ORDER BY balance_date DESC
  LIMIT 1;

  SELECT COALESCE(SUM(usdt_delta), 0) INTO v_total_contributions
  FROM lth_pvr.ledger_lines
  WHERE portfolio_id = p_portfolio_id
  AND event_type = 'deposit';

  v_result := jsonb_build_object(
    'portfolio_id', p_portfolio_id,
    'customer_id', v_customer_id,
    'btc_balance', COALESCE(v_latest_balance.btc_balance, 0),
    'usdt_balance', COALESCE(v_latest_balance.usdt_balance, 0),
    'usdpc_balance', COALESCE(v_latest_balance.usdpc_balance, 0),
    'usdpc_price_usd', v_latest_balance.usdpc_price_usd,
    'usdpc_value_usd', COALESCE(v_latest_balance.usdpc_balance, 0) * COALESCE(v_latest_balance.usdpc_price_usd, 1),
    'nav_usd', COALESCE(v_latest_balance.nav_usd, 0),
    'roi_pct', COALESCE(v_latest_balance.roi_pct, 0),
    'cagr_pct', COALESCE(v_latest_balance.cagr_pct, 0),
    'total_contributions', v_total_contributions,
    'last_updated', COALESCE(v_latest_balance.balance_date, CURRENT_DATE)
  );

  RETURN v_result;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.get_customer_exchange_account(p_customer_id bigint)
 RETURNS TABLE(exchange_account_id uuid, bank_name text, bank_account_number text, bank_account_holder text, bank_branch_code text, bank_account_type text, bank_account_id uuid, bank_valr_id text, bank_linked_at timestamp with time zone, bank_link_method text, api_key_label text, api_key_verified_at timestamp with time zone, api_key_expires_at timestamp with time zone, api_key_has_trade boolean, api_key_has_withdraw boolean, api_key_has_view boolean, api_key_has_link_bank boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  PERFORM public.assert_customer_access(p_customer_id::bigint);
  RETURN QUERY
  SELECT ea.exchange_account_id, ba.bank_name, ba.bank_account_number, ba.bank_account_holder,
    ba.bank_branch_code, ba.bank_account_type, ba.bank_account_id, ea.bank_valr_id,
    ea.bank_linked_at, ea.bank_link_method, ea.api_key_label, ea.api_key_verified_at,
    ea.api_key_expires_at, ea.api_key_has_trade, ea.api_key_has_withdraw, ea.api_key_has_view, ea.api_key_has_link_bank
  FROM public.exchange_accounts ea
  JOIN public.customer_strategies cs ON cs.exchange_account_id = ea.exchange_account_id
  LEFT JOIN public.bank_accounts ba ON ba.bank_account_id = ea.bank_account_id AND ba.status = 'active'
  WHERE cs.customer_id = p_customer_id AND cs.status NOT IN ('closed', 'terminated')
  ORDER BY cs.created_at DESC LIMIT 1;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.get_customer_fee_rates(p_customer_ids bigint[] DEFAULT NULL::bigint[])
 RETURNS TABLE(customer_id bigint, performance_fee_rate numeric, performance_fee_percentage numeric, platform_fee_rate numeric, platform_fee_percentage numeric, performance_fee_schedule text, platform_fee_schedule text, fee_plan text, management_fee_rate numeric, management_fee_percentage numeric, management_fee_schedule text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM public.assert_org_admin();
  RETURN QUERY
  SELECT cs.customer_id,
    COALESCE(cs.performance_fee_rate, 0.10),
    COALESCE(cs.performance_fee_rate, 0.10) * 100,
    COALESCE(cs.platform_fee_rate, 0.0075),
    COALESCE(cs.platform_fee_rate, 0.0075) * 100,
    COALESCE(cs.performance_fee_schedule, 'monthly')::text,
    COALESCE(cs.platform_fee_schedule, 'immediate')::text,
    COALESCE(cs.fee_plan, 'platform')::text,
    COALESCE(cs.management_fee_rate, 0.01),
    COALESCE(cs.management_fee_rate, 0.01) * 100,
    COALESCE(cs.management_fee_schedule, 'monthly')::text
  FROM public.customer_strategies cs
  WHERE cs.strategy_code IN ('LTH_PVR','STH_CB')
    AND (p_customer_ids IS NULL OR array_length(p_customer_ids,1) IS NULL OR cs.customer_id = ANY(p_customer_ids))
    AND (p_customer_ids IS NOT NULL OR cs.status = 'active')
  ORDER BY cs.customer_id;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.get_customer_fee_rates_asof(p_customer_id bigint, p_as_of date)
 RETURNS TABLE(fee_plan text, platform_fee_rate numeric, platform_fee_schedule text, management_fee_rate numeric, management_fee_schedule text, performance_fee_rate numeric, performance_fee_schedule text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM public.assert_customer_access(p_customer_id::bigint);
  RETURN QUERY
  SELECT h.fee_plan, h.platform_fee_rate, h.platform_fee_schedule, h.management_fee_rate,
         h.management_fee_schedule, h.performance_fee_rate, h.performance_fee_schedule
  FROM public.customer_fee_plan_history h
  WHERE h.customer_id=p_customer_id AND h.strategy_code IN ('LTH_PVR','STH_CB')
    AND h.effective_from <= p_as_of AND (h.effective_to IS NULL OR h.effective_to >= p_as_of)
  ORDER BY h.effective_from DESC LIMIT 1;
  IF NOT FOUND THEN
    RETURN QUERY SELECT cs.fee_plan, cs.platform_fee_rate, cs.platform_fee_schedule, cs.management_fee_rate,
      cs.management_fee_schedule, cs.performance_fee_rate, cs.performance_fee_schedule
    FROM public.customer_strategies cs WHERE cs.customer_id=p_customer_id AND cs.strategy_code IN ('LTH_PVR','STH_CB') LIMIT 1;
  END IF;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.get_customer_onboarding_status(p_customer_id integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_result JSONB;
  v_customer RECORD;
  v_bank_conf_url TEXT;
  v_milestone INT;
  v_milestones JSONB;
  v_next_action TEXT;
  v_portal_access BOOLEAN;
  v_docs_uploaded INT;
  v_all_kyc_docs BOOLEAN;
BEGIN
  PERFORM public.assert_customer_access(p_customer_id::bigint);
  SELECT
    registration_status,
    kyc_id_document_url,
    kyc_proof_address_url,
    kyc_source_of_income,
    kyc_source_of_income_doc_url,
    created_at
  INTO v_customer
  FROM public.customer_details
  WHERE customer_id = p_customer_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'Customer not found');
  END IF;

  -- Bank confirmation now lives on public.bank_accounts (single source of truth).
  SELECT bank_confirmation_url
  INTO v_bank_conf_url
  FROM public.bank_accounts
  WHERE customer_id = p_customer_id AND is_primary
  LIMIT 1;

  v_all_kyc_docs :=
    v_customer.kyc_id_document_url          IS NOT NULL AND
    v_customer.kyc_proof_address_url         IS NOT NULL AND
    v_customer.kyc_source_of_income          IS NOT NULL AND
    v_customer.kyc_source_of_income_doc_url  IS NOT NULL AND
    v_bank_conf_url                          IS NOT NULL;

  v_docs_uploaded :=
    (CASE WHEN v_customer.kyc_id_document_url          IS NOT NULL THEN 1 ELSE 0 END) +
    (CASE WHEN v_customer.kyc_proof_address_url         IS NOT NULL THEN 1 ELSE 0 END) +
    (CASE WHEN v_customer.kyc_source_of_income_doc_url  IS NOT NULL THEN 1 ELSE 0 END) +
    (CASE WHEN v_bank_conf_url                          IS NOT NULL THEN 1 ELSE 0 END);

  CASE v_customer.registration_status
    WHEN 'prospect' THEN
      v_milestone := 1;
      v_next_action := 'Waiting for admin to confirm interest and select strategy';
    WHEN 'kyc' THEN
      v_milestone := 3;
      IF v_all_kyc_docs THEN
        v_next_action := 'All KYC documents received - verification in progress';
      ELSE
        v_next_action := 'Please upload all required KYC documents (' || v_docs_uploaded || '/4 complete)';
      END IF;
    WHEN 'setup' THEN
      v_milestone := 4;
      v_next_action := 'VALR account being set up - you will receive deposit instructions soon';
    WHEN 'deposit' THEN
      v_milestone := 5;
      v_next_action := 'Waiting for your initial deposit';
    WHEN 'active' THEN
      v_milestone := 6;
      v_next_action := 'Account active - trading commenced';
    WHEN 'inactive' THEN
      v_milestone := 6;
      v_next_action := 'Account inactive';
    ELSE
      v_milestone := 1;
      v_next_action := 'Status: ' || v_customer.registration_status;
  END CASE;

  v_milestones := jsonb_build_array(
    v_milestone >= 1, v_milestone >= 2, v_milestone >= 3,
    v_milestone >= 4, v_milestone >= 5, v_milestone >= 6
  );

  v_portal_access := v_milestone >= 3;

  v_result := jsonb_build_object(
    'customer_id',                p_customer_id,
    'current_milestone',          v_milestone,
    'milestone_statuses',         v_milestones,
    'next_action',                v_next_action,
    'portal_access_granted',      v_portal_access,
    'registration_status',        v_customer.registration_status,
    'kyc_id_uploaded',            v_customer.kyc_id_document_url IS NOT NULL,
    'kyc_docs_uploaded',          v_docs_uploaded,
    'kyc_all_docs_uploaded',      v_all_kyc_docs,
    'kyc_id_doc_uploaded',        v_customer.kyc_id_document_url          IS NOT NULL,
    'kyc_proof_address_uploaded', v_customer.kyc_proof_address_url         IS NOT NULL,
    'kyc_source_of_income_set',   v_customer.kyc_source_of_income          IS NOT NULL,
    'kyc_income_doc_uploaded',    v_customer.kyc_source_of_income_doc_url  IS NOT NULL,
    'kyc_bank_conf_uploaded',     v_bank_conf_url                          IS NOT NULL,
    'created_at',                 v_customer.created_at
  );

  RETURN v_result;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.get_customer_pipeline_status(p_org_id uuid, p_date date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'lth_pvr'
AS $function$
DECLARE
  v_now            timestamptz := now();
  v_today          date        := (v_now AT TIME ZONE 'UTC')::date;
  v_is_today       boolean     := (p_date = v_today);
  v_signal_date    date        := p_date - 1;
  v_minutes        int         := EXTRACT(EPOCH FROM ((v_now AT TIME ZONE 'UTC') - p_date::timestamp)) / 60;
  v_rb_row         record;
  v_decisions_n    int;
  v_org_ci_status  text;   -- key name kept for UI JSON compatibility
  v_org_dec_status text;
  v_org_ci_ts      timestamptz;
  v_org_ci_label   text;
  v_org_dec_label  text;
  v_customers      jsonb;
BEGIN
  PERFORM public.assert_org_admin();
  -- RB bands for the SIGNAL date (yesterday relative to trade date)
  SELECT fetched_at INTO v_rb_row
  FROM lth_pvr.rb_bands_daily
  WHERE org_id = p_org_id AND date = v_signal_date
  LIMIT 1;

  IF v_rb_row.fetched_at IS NOT NULL THEN
    v_org_ci_status := 'complete';
    v_org_ci_ts     := v_rb_row.fetched_at;
    v_org_ci_label  := 'RB bands for ' || to_char(v_signal_date,'YYYY-MM-DD')
                       || ' fetched ' || to_char(v_rb_row.fetched_at AT TIME ZONE 'UTC','HH24:MI') || ' UTC';
  ELSIF v_is_today AND v_minutes < 5 THEN
    v_org_ci_status := 'not_started'; v_org_ci_label := 'Scheduled 00:05 UTC';
  ELSIF v_is_today AND v_minutes < 30 THEN
    v_org_ci_status := 'in_progress'; v_org_ci_label := 'Fetching RB bands…';
  ELSE
    v_org_ci_status := 'failed';
    v_org_ci_label  := 'RB bands missing for signal date ' || to_char(v_signal_date,'YYYY-MM-DD');
  END IF;

  SELECT count(*) INTO v_decisions_n FROM lth_pvr.decisions_daily WHERE org_id = p_org_id AND trade_date = p_date;
  IF v_decisions_n > 0 THEN
    v_org_dec_status := 'complete'; v_org_dec_label := v_decisions_n || ' decisions generated';
  ELSIF v_org_ci_status <> 'complete' THEN
    v_org_dec_status := 'not_started'; v_org_dec_label := 'Waiting on RB bands';
  ELSIF v_is_today AND v_minutes < 10 THEN
    v_org_dec_status := 'not_started'; v_org_dec_label := 'Scheduled 00:10 UTC';
  ELSIF v_is_today AND v_minutes < 35 THEN
    v_org_dec_status := 'in_progress'; v_org_dec_label := 'Generating decisions…';
  ELSE
    v_org_dec_status := 'failed'; v_org_dec_label := 'Decisions not generated';
  END IF;

  WITH active_customers AS (
    SELECT cd.customer_id,
           TRIM(COALESCE(cd.first_names,'')||' '||COALESCE(cd.last_name,'')) AS customer_name,
           cd.registration_status, ea.label AS account_label
    FROM public.customer_details cd
    JOIN public.customer_strategies cs ON cs.customer_id=cd.customer_id AND cs.org_id=p_org_id AND cs.status='active' AND cs.strategy_code='LTH_PVR'
    JOIN public.exchange_accounts ea ON ea.exchange_account_id=cs.exchange_account_id AND ea.org_id=p_org_id AND ea.status='active'
    WHERE cd.org_id = p_org_id
  ),
  cust_decision AS (
    SELECT customer_id, action, amount_pct, rule, note FROM lth_pvr.decisions_daily WHERE org_id=p_org_id AND trade_date=p_date
  ),
  cust_state AS (
    SELECT customer_id, bear_pause
    FROM lth_pvr.customer_state_daily WHERE org_id=p_org_id AND date=v_signal_date
  ),
  -- BTC trade intent (exclude USDPC/USDT conversions; those are tracked separately)
  cust_intent AS (
    SELECT DISTINCT ON (customer_id) customer_id, intent_id, status, side, pair, amount, limit_price, created_at, reason
    FROM lth_pvr.order_intents
    WHERE org_id=p_org_id AND trade_date=p_date AND pair <> 'USDPC/USDT'
    ORDER BY customer_id, created_at DESC
  ),
  cust_skip_alert AS (
    SELECT DISTINCT ON ((context->>'customer_id')::bigint)
           (context->>'customer_id')::bigint AS customer_id,
           message
    FROM public.alert_events
    WHERE component = 'ef_create_order_intents'
      AND (context->>'trade_date')::date = p_date
      AND context ? 'customer_id'
    ORDER BY (context->>'customer_id')::bigint, created_at DESC
  ),
  -- BTC exchange order (exclude USDPC/USDT conversions)
  cust_order AS (
    SELECT DISTINCT ON (oi.customer_id) oi.customer_id, eo.exchange_order_id, eo.status, eo.side, eo.pair, eo.qty, eo.price, eo.submitted_at, eo.updated_at
    FROM lth_pvr.exchange_orders eo JOIN lth_pvr.order_intents oi ON oi.intent_id=eo.intent_id
    WHERE eo.org_id=p_org_id AND oi.trade_date=p_date AND eo.pair <> 'USDPC/USDT'
    ORDER BY oi.customer_id, eo.submitted_at DESC
  ),
  -- USDPC yield conversions (sweep USDT->USDPC, or pre-buy USDPC->USDT). One
  -- intent == one market order; aggregate fill status so the UI can show a
  -- single "Convert" light that turns green only when every chunk filled.
  cust_convert AS (
    SELECT oi.customer_id,
           count(DISTINCT oi.intent_id) AS n_intents,
           count(DISTINCT oi.intent_id) FILTER (WHERE oi.status IN ('failed','rejected','cancelled')) AS n_failed_intents,
           count(DISTINCT eo.exchange_order_id) FILTER (WHERE upper(coalesce(eo.status,'')) IN ('FILLED','COMPLETED')) AS n_filled_orders,
           count(DISTINCT eo.exchange_order_id) FILTER (WHERE upper(coalesce(eo.status,'')) IN ('CANCELLED','REJECTED','FAILED')) AS n_failed_orders,
           bool_or(oi.reason = 'usdpc_prebuy_convert') AS has_prebuy,
           bool_or(oi.reason = 'usdpc_sweep') AS has_sweep,
           max(coalesce(eo.updated_at, eo.submitted_at, oi.created_at)) AS last_at
    FROM lth_pvr.order_intents oi
    LEFT JOIN lth_pvr.exchange_orders eo ON eo.intent_id = oi.intent_id AND eo.org_id = p_org_id
    WHERE oi.org_id = p_org_id AND oi.trade_date = p_date AND oi.pair = 'USDPC/USDT'
    GROUP BY oi.customer_id
  ),
  cust_settle AS (
    SELECT customer_id, bool_or(kind IN ('buy','sell','trade')) AS posted, max(created_at) AS posted_at, sum(amount_btc) AS btc, sum(amount_usdt) AS usdt
    FROM lth_pvr.ledger_lines WHERE org_id=p_org_id AND trade_date=p_date GROUP BY customer_id
  )
  SELECT jsonb_agg(
    jsonb_build_object(
      'customer_id', ac.customer_id,
      'customer_name', ac.customer_name,
      'registration_status', ac.registration_status,
      'account_label', ac.account_label,
      'decision', jsonb_build_object(
        'status', CASE
          WHEN cd.customer_id IS NOT NULL THEN 'complete'
          WHEN v_org_dec_status = 'complete' THEN 'na'
          WHEN v_org_dec_status = 'failed'   THEN 'failed'
          WHEN v_org_dec_status = 'in_progress' THEN 'in_progress'
          ELSE 'not_started'
        END,
        'action', cd.action,
        'label', CASE
          WHEN cd.action IS NULL AND v_org_dec_status='complete' THEN 'Skipped (no qualifying balance / inactive)'
          WHEN cd.action IS NULL THEN v_org_dec_label
          WHEN cd.action = 'HOLD' THEN 'HOLD — ' || COALESCE(cd.rule,'no qualifying signal')
          ELSE cd.action || ' ' || COALESCE(round(cd.amount_pct,1)::text||'%','') || ' (' || COALESCE(cd.rule,'') || ')'
        END
      ),
      'intent', CASE
        WHEN cd.action = 'HOLD' THEN jsonb_build_object('status','na','label','No order required (HOLD)')
        WHEN cd.customer_id IS NULL AND v_org_dec_status='complete' THEN jsonb_build_object('status','na','label','—')
        WHEN ci.intent_id IS NOT NULL THEN jsonb_build_object(
          'status', CASE ci.status WHEN 'pending' THEN 'in_progress' WHEN 'submitted' THEN 'complete' WHEN 'filled' THEN 'complete' WHEN 'executed' THEN 'complete' WHEN 'failed' THEN 'failed' WHEN 'rejected' THEN 'failed' WHEN 'cancelled' THEN 'failed' ELSE 'in_progress' END,
          'label', ci.side||' '||coalesce(ci.amount::text,'')||' '||coalesce(ci.pair,'')||COALESCE(' @ '||ci.limit_price::text,'')||' — '||ci.status
        )
        WHEN cd.customer_id IS NULL THEN jsonb_build_object('status','not_started','label','Awaiting decision')
        WHEN COALESCE(st.bear_pause,false) THEN jsonb_build_object('status','na','label','Skipped — Bear Market Pause active')
        WHEN sa.message IS NOT NULL THEN jsonb_build_object('status','na','label','Skipped — '||sa.message)
        WHEN v_is_today AND v_minutes < 10 THEN jsonb_build_object('status','not_started','label','Scheduled 00:10 UTC')
        WHEN v_is_today AND v_minutes < 35 THEN jsonb_build_object('status','in_progress','label','Sizing order…')
        ELSE jsonb_build_object('status','failed','label','Order intent missing')
      END,
      'execute', CASE
        WHEN cd.action = 'HOLD' THEN jsonb_build_object('status','na','label','—')
        WHEN cd.customer_id IS NULL AND v_org_dec_status='complete' THEN jsonb_build_object('status','na','label','—')
        WHEN COALESCE(st.bear_pause,false) AND ci.intent_id IS NULL THEN jsonb_build_object('status','na','label','—')
        WHEN sa.message IS NOT NULL AND ci.intent_id IS NULL THEN jsonb_build_object('status','na','label','—')
        WHEN co.exchange_order_id IS NOT NULL THEN jsonb_build_object(
          'status', CASE upper(coalesce(co.status,'')) WHEN 'PLACED' THEN 'in_progress' WHEN 'PARTIALLY_FILLED' THEN 'in_progress' WHEN 'OPEN' THEN 'in_progress' WHEN 'PENDING' THEN 'in_progress' WHEN 'FILLED' THEN 'complete' WHEN 'COMPLETED' THEN 'complete' WHEN 'CANCELLED' THEN 'failed' WHEN 'REJECTED' THEN 'failed' WHEN 'FAILED' THEN 'failed' ELSE 'in_progress' END,
          'label', co.side||' '||coalesce(co.qty::text,'')||' '||coalesce(co.pair,'')||COALESCE(' @ '||co.price::text,'')||' — '||coalesce(co.status,'?')
        )
        WHEN ci.intent_id IS NULL THEN jsonb_build_object('status','not_started','label','Awaiting intent')
        WHEN v_is_today AND v_minutes < 15 THEN jsonb_build_object('status','not_started','label','Scheduled 00:15 UTC')
        WHEN v_is_today AND v_minutes < 40 THEN jsonb_build_object('status','in_progress','label','Placing order on VALR…')
        ELSE jsonb_build_object('status','failed','label','Order not placed')
      END,
      'settle', CASE
        WHEN cd.action = 'HOLD' THEN jsonb_build_object('status','na','label','—')
        WHEN cd.customer_id IS NULL AND v_org_dec_status='complete' THEN jsonb_build_object('status','na','label','—')
        WHEN COALESCE(st.bear_pause,false) AND ci.intent_id IS NULL THEN jsonb_build_object('status','na','label','—')
        WHEN sa.message IS NOT NULL AND ci.intent_id IS NULL THEN jsonb_build_object('status','na','label','—')
        WHEN cs.posted THEN jsonb_build_object('status','complete','label','Settled '||COALESCE(round(cs.btc,8)::text||' BTC ','')||COALESCE('@ '||round(cs.usdt,2)::text||' USDT','')||' ('||to_char(cs.posted_at AT TIME ZONE 'UTC','HH24:MI')||' UTC)')
        WHEN co.exchange_order_id IS NULL THEN jsonb_build_object('status','not_started','label','Awaiting fills')
        WHEN upper(coalesce(co.status,'')) IN ('FILLED','COMPLETED') THEN jsonb_build_object('status','in_progress','label','Posting to ledger…')
        WHEN upper(coalesce(co.status,'')) IN ('CANCELLED','REJECTED','FAILED') THEN jsonb_build_object('status','na','label','Order did not fill')
        ELSE jsonb_build_object('status','not_started','label','Awaiting fills')
      END,
      'convert', CASE
        WHEN cc.customer_id IS NULL THEN jsonb_build_object('status','na','label','No USDPC conversion')
        WHEN cc.n_failed_intents > 0 OR cc.n_failed_orders > 0 THEN jsonb_build_object('status','failed',
          'label','USDPC conversion failed — '||cc.n_filled_orders::text||'/'||cc.n_intents::text||' filled')
        WHEN cc.n_filled_orders >= cc.n_intents AND cc.n_intents > 0 THEN jsonb_build_object('status','complete',
          'label','USDPC '||CASE WHEN cc.has_prebuy AND cc.has_sweep THEN 'convert' WHEN cc.has_prebuy THEN 'pre-buy convert' ELSE 'sweep' END
            ||' filled ('||cc.n_filled_orders::text||'/'||cc.n_intents::text||')'
            ||COALESCE(' '||to_char(cc.last_at AT TIME ZONE 'UTC','HH24:MI')||' UTC',''))
        ELSE jsonb_build_object('status','in_progress',
          'label','USDPC '||CASE WHEN cc.has_prebuy AND cc.has_sweep THEN 'convert' WHEN cc.has_prebuy THEN 'pre-buy convert' ELSE 'sweep' END
            ||' in progress ('||cc.n_filled_orders::text||'/'||cc.n_intents::text||' filled)')
      END,
      'subtitle', jsonb_build_object(
        'step', CASE
          WHEN cs.posted THEN 'Settled'
          WHEN co.exchange_order_id IS NOT NULL THEN 'Executing'
          WHEN ci.intent_id IS NOT NULL THEN 'Sizing order'
          WHEN cd.customer_id IS NOT NULL AND COALESCE(st.bear_pause,false) THEN 'Bear Market Pause'
          WHEN cd.customer_id IS NOT NULL AND sa.message IS NOT NULL THEN 'Order skipped'
          WHEN cd.customer_id IS NOT NULL THEN CASE WHEN cd.action='HOLD' THEN 'Hold' ELSE 'Decision ready' END
          WHEN v_org_dec_status = 'complete' THEN 'Skipped today'
          WHEN v_org_dec_status = 'failed'   THEN 'Pipeline failed'
          ELSE 'Waiting on pipeline'
        END,
        'detail', CASE
          WHEN cs.posted THEN 'Last activity '||to_char(cs.posted_at AT TIME ZONE 'UTC','HH24:MI')||' UTC'
          WHEN co.exchange_order_id IS NOT NULL THEN co.side||' '||coalesce(co.qty::text,'')||' '||coalesce(co.pair,'')||COALESCE(' @ '||co.price::text,'')||' — '||coalesce(co.status,'?')
          WHEN ci.intent_id IS NOT NULL THEN ci.side||' '||coalesce(ci.amount::text,'')||' '||coalesce(ci.pair,'')||' — '||ci.status
          WHEN cd.customer_id IS NOT NULL AND COALESCE(st.bear_pause,false) THEN 'No orders generated while BTC is below the bear-pause exit threshold'
          WHEN cd.customer_id IS NOT NULL AND sa.message IS NOT NULL THEN sa.message
          WHEN cd.customer_id IS NOT NULL THEN COALESCE(cd.note, COALESCE(cd.action,'')||' ('||COALESCE(cd.rule,'')||')')
          WHEN v_org_dec_status = 'complete' THEN 'No qualifying decision generated for this customer'
          ELSE v_org_dec_label
        END
      )
    )
    ORDER BY ac.registration_status NULLS LAST, ac.customer_name
  )
  INTO v_customers
  FROM active_customers ac
  LEFT JOIN cust_decision  cd ON cd.customer_id=ac.customer_id
  LEFT JOIN cust_state     st ON st.customer_id=ac.customer_id
  LEFT JOIN cust_intent    ci ON ci.customer_id=ac.customer_id
  LEFT JOIN cust_skip_alert sa ON sa.customer_id=ac.customer_id
  LEFT JOIN cust_order     co ON co.customer_id=ac.customer_id
  LEFT JOIN cust_convert   cc ON cc.customer_id=ac.customer_id
  LEFT JOIN cust_settle    cs ON cs.customer_id=ac.customer_id;

  RETURN jsonb_build_object(
    'date', p_date, 'is_today', v_is_today, 'now_utc', v_now,
    'signal_date', v_signal_date,
    'org_steps', jsonb_build_object(
      'ci_bands',  jsonb_build_object('status', v_org_ci_status,  'label', v_org_ci_label,  'ts', v_org_ci_ts),
      'decisions', jsonb_build_object('status', v_org_dec_status, 'label', v_org_dec_label)
    ),
    'customers', COALESCE(v_customers, '[]'::jsonb)
  );
END;
$function$
;

