CREATE OR REPLACE FUNCTION public.list_accumulated_fees(p_org_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(customer_id bigint, customer_name text, email text, accumulated_btc numeric, accumulated_usdt numeric, accumulated_zar numeric, total_usd numeric, last_updated_at timestamp with time zone, last_transfer_attempt_at timestamp with time zone, transfer_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_org_id UUID;
  v_btc_price NUMERIC(38,2);
BEGIN
  PERFORM public.assert_org_admin();
  v_org_id := COALESCE(p_org_id, (SELECT id FROM public.organizations LIMIT 1));
  SELECT btc_price INTO v_btc_price FROM lth_pvr.ci_bands_daily ORDER BY date DESC LIMIT 1;
  IF v_btc_price IS NULL THEN v_btc_price := 100000; END IF;
  
  RETURN QUERY
  SELECT caf.customer_id, cd.first_names || ' ' || cd.last_name, cd.email,
    caf.accumulated_btc, caf.accumulated_usdt, caf.accumulated_zar,
    (caf.accumulated_btc * v_btc_price) + caf.accumulated_usdt + (caf.accumulated_zar / 18.5),
    caf.last_updated_at, caf.last_transfer_attempt_at, caf.transfer_count
  FROM lth_pvr.customer_accumulated_fees caf
  JOIN public.customer_details cd ON caf.customer_id = cd.customer_id
  WHERE caf.org_id = v_org_id AND (caf.accumulated_btc > 0 OR caf.accumulated_usdt > 0 OR caf.accumulated_zar > 0)
  ORDER BY total_usd DESC;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.list_customer_portfolios(p_customer_id bigint)
 RETURNS TABLE(portfolio_id uuid, strategy_code text, strategy_name text, status text, nav_usd numeric, btc_balance numeric, usdt_balance numeric, usdpc_balance numeric, usdpc_price_usd numeric, usdpc_value_usd numeric, btc_price numeric, total_contributions numeric, has_trading_history boolean, created_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
begin
  PERFORM public.assert_customer_access(p_customer_id::bigint);
  return query
  select
    cs.portfolio_id,
    cs.strategy_code,
    coalesce(s.name, cs.strategy_code || ' Strategy')::text as strategy_name,
    cs.status,
    coalesce(latest_balance.nav_usd, 0) as nav_usd,
    coalesce(latest_balance.btc_balance, 0) as btc_balance,
    coalesce(latest_balance.usdt_balance, 0) as usdt_balance,
    coalesce(latest_balance.usdpc_balance, 0) as usdpc_balance,
    latest_balance.usdpc_price_usd as usdpc_price_usd,
    (coalesce(latest_balance.usdpc_balance, 0) * coalesce(latest_balance.usdpc_price_usd, 1)) as usdpc_value_usd,
    coalesce(latest_price.btc_price, 0) as btc_price,
    coalesce(contrib.net_usdt, 0) as total_contributions,
    exists(
      select 1 from lth_pvr.decisions_daily dd where dd.customer_id = p_customer_id
      union all select 1 from sth_cb.decisions_daily sd where sd.customer_id = p_customer_id limit 1
    ) as has_trading_history,
    cs.created_at
  from public.customer_strategies cs
  left join public.strategies s on s.strategy_code = cs.strategy_code
  left join lateral (
    select bd.btc_balance, bd.usdt_balance, bd.usdpc_balance, bd.usdpc_price_usd, bd.nav_usd
    from lth_pvr.balances_daily bd
    where bd.customer_id = p_customer_id and bd.date <= current_date
    order by bd.date desc limit 1
  ) latest_balance on true
  left join lateral (
    select cb.btc_price
    from lth_pvr.ci_bands_daily cb
    where cb.date <= current_date
    order by cb.date desc limit 1
  ) latest_price on true
  left join lateral (
    select
      coalesce(sum(case when kind = 'topup'      then amount_usdt else 0 end), 0)
      + coalesce(sum(case when kind = 'withdrawal' then amount_usdt else 0 end), 0) as net_usdt
    from lth_pvr.ledger_lines
    where customer_id = p_customer_id
  ) contrib on true
  where cs.customer_id = p_customer_id
  order by cs.created_at desc;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.list_customer_transactions(p_customer_id bigint, p_limit integer DEFAULT 100)
 RETURNS TABLE(trade_date date, kind text, amount_btc numeric, amount_usdt numeric, amount_zar numeric, amount_usdpc numeric, fee_btc numeric, fee_usdt numeric, fee_usdpc numeric, platform_fee_btc numeric, platform_fee_usdt numeric, management_fee_usdt numeric, note text, conversion_metadata jsonb, ext_ref text, created_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  PERFORM public.assert_customer_access(p_customer_id::bigint);
  RETURN QUERY
  WITH base AS (
    SELECT
      ll.ledger_id, ll.trade_date, ll.kind,
      ll.amount_btc, ll.amount_usdt, ll.amount_zar, ll.amount_usdpc,
      ll.fee_btc, ll.fee_usdt, ll.fee_usdpc,
      ll.platform_fee_btc, ll.platform_fee_usdt, ll.management_fee_usdt,
      ll.note, ll.conversion_metadata, fe.ext_ref, ll.created_at,
      COALESCE(
        NULLIF(ll.conversion_metadata->>'original_transaction_id',''),
        ll.conversion_approval_id::text
      ) AS conv_key
    FROM lth_pvr.ledger_lines ll
    LEFT JOIN lth_pvr.exchange_funding_events fe
      ON ll.note = 'funding:' || fe.funding_id::text
    WHERE ll.customer_id = p_customer_id
  ),
  conv_groups AS (
    SELECT conv_key FROM base WHERE conv_key IS NOT NULL GROUP BY conv_key HAVING count(*) > 1
  ),
  flagged AS (
    SELECT b.*, (cg.conv_key IS NOT NULL) AS is_conv_group
    FROM base b LEFT JOIN conv_groups cg ON cg.conv_key = b.conv_key
  ),
  merged AS (
    SELECT
      max(f.trade_date) AS trade_date,
      'conversion'::text AS kind,
      sum(f.amount_btc) AS amount_btc,
      sum(f.amount_usdt) AS amount_usdt,
      sum(f.amount_zar) AS amount_zar,
      sum(f.amount_usdpc) AS amount_usdpc,
      sum(f.fee_btc) AS fee_btc,
      sum(f.fee_usdt) AS fee_usdt,
      sum(f.fee_usdpc) AS fee_usdpc,
      sum(f.platform_fee_btc) AS platform_fee_btc,
      sum(f.platform_fee_usdt) AS platform_fee_usdt,
      sum(f.management_fee_usdt) AS management_fee_usdt,
      string_agg(DISTINCT f.note, ' | ') AS note,
      COALESCE(
        (SELECT f2.conversion_metadata FROM flagged f2
         WHERE f2.conv_key = f.conv_key
           AND (f2.conversion_metadata ? 'conversion_to' OR f2.conversion_metadata ? 'conversion_from') LIMIT 1),
        (SELECT f2.conversion_metadata FROM flagged f2
         WHERE f2.conv_key = f.conv_key AND f2.conversion_metadata <> '{}'::jsonb LIMIT 1),
        '{}'::jsonb
      ) AS conversion_metadata,
      max(f.ext_ref) AS ext_ref,
      max(f.created_at) AS created_at
    FROM flagged f WHERE f.is_conv_group GROUP BY f.conv_key
  ),
  passthru AS (
    SELECT
      f.trade_date, f.kind, f.amount_btc, f.amount_usdt, f.amount_zar, f.amount_usdpc,
      f.fee_btc, f.fee_usdt, f.fee_usdpc, f.platform_fee_btc, f.platform_fee_usdt, f.management_fee_usdt,
      f.note, f.conversion_metadata, f.ext_ref, f.created_at
    FROM flagged f WHERE NOT f.is_conv_group
  )
  SELECT * FROM (
    SELECT * FROM merged
    UNION ALL
    SELECT * FROM passthru
  ) u
  ORDER BY u.trade_date DESC, u.created_at DESC
  LIMIT p_limit;
END;
$function$
;

