CREATE OR REPLACE FUNCTION public.regenerate_kyc_signed_url(p_customer_id integer)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_file_path TEXT;
  v_signed_url TEXT;
BEGIN
  PERFORM public.assert_customer_access(p_customer_id::bigint);
  -- Extract file path from existing URL
  SELECT 
    REGEXP_REPLACE(
      kyc_id_document_url, 
      '^https://[^/]+/storage/v1/object/(public|sign)/kyc-documents/', 
      ''
    )
  INTO v_file_path
  FROM customer_details
  WHERE customer_id = p_customer_id;

  -- Note: SQL cannot directly call Supabase Storage API
  -- Return the file path for manual processing
  RETURN v_file_path;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.resolve_lth_alert_event(p_alert_id uuid, p_resolved_by text, p_resolution_note text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM public.assert_org_admin();
  UPDATE public.alert_events
     SET resolved_at     = now(),
         resolved_by     = p_resolved_by,
         resolution_note = COALESCE(p_resolution_note, resolution_note)
   WHERE alert_id    = p_alert_id
     AND resolved_at IS NULL;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.review_triage_proposal(p_proposal_id uuid, p_action text, p_reviewer text, p_note text DEFAULT NULL::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_alert_id uuid;
BEGIN
  PERFORM public.assert_org_admin();
  IF p_action NOT IN ('accept','reject') THEN
    RAISE EXCEPTION 'invalid action: %', p_action;
  END IF;

  IF p_action = 'accept' THEN
    UPDATE public.alert_triage_proposals
       SET accepted_at  = now(),
           accepted_by  = p_reviewer,
           reviewer_note= p_note
     WHERE proposal_id  = p_proposal_id
       AND accepted_at IS NULL
       AND rejected_at IS NULL
     RETURNING alert_id INTO v_alert_id;
  ELSE
    UPDATE public.alert_triage_proposals
       SET rejected_at  = now(),
           rejected_by  = p_reviewer,
           reviewer_note= p_note
     WHERE proposal_id  = p_proposal_id
       AND accepted_at IS NULL
       AND rejected_at IS NULL
     RETURNING alert_id INTO v_alert_id;
  END IF;

  IF v_alert_id IS NULL THEN
    RAISE EXCEPTION 'proposal not found or already reviewed';
  END IF;

  RETURN json_build_object('proposal_id', p_proposal_id, 'alert_id', v_alert_id, 'action', p_action);
END
$function$
;
CREATE OR REPLACE FUNCTION public.run_public_backtest(p_email text, p_start_date date, p_end_date date, p_upfront_usdt numeric, p_monthly_usdt numeric)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_request_id UUID;
    v_bt_run_id UUID;
    v_remaining INTEGER;
    v_org_id UUID := 'b0a77009-03b9-44a1-ae1d-34f157d44a8b'::uuid;  -- Real org_id with CI bands data
BEGIN
  PERFORM public.assert_org_admin();
    -- Validate email format
    IF p_email !~ '^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$' THEN
        RETURN json_build_object(
            'success', false,
            'error', 'Invalid email format'
        );
    END IF;
    
    -- Check rate limit
    IF NOT public.check_backtest_rate_limit(p_email) THEN
        RETURN json_build_object(
            'success', false,
            'error', 'Rate limit exceeded. Maximum 10 back-tests per day per email.',
            'remaining', 0
        );
    END IF;
    
    -- Validate date range
    IF p_start_date >= p_end_date THEN
        RETURN json_build_object(
            'success', false,
            'error', 'End date must be after start date'
        );
    END IF;
    
    IF p_end_date > CURRENT_DATE THEN
        RETURN json_build_object(
            'success', false,
            'error', 'End date cannot be in the future'
        );
    END IF;
    
    -- Validate amounts
    IF p_upfront_usdt < 0 OR p_monthly_usdt < 0 THEN
        RETURN json_build_object(
            'success', false,
            'error', 'Investment amounts must be positive'
        );
    END IF;
    
    IF p_upfront_usdt = 0 AND p_monthly_usdt = 0 THEN
        RETURN json_build_object(
            'success', false,
            'error', 'At least one investment amount must be greater than zero'
        );
    END IF;
    
    -- Generate bt_run_id
    v_bt_run_id := gen_random_uuid();
    
    -- 1. Create back-test run record FIRST (for foreign key)
    INSERT INTO lth_pvr_bt.bt_runs (
        bt_run_id,
        org_id,
        customer_id,
        started_at,
        status
    ) VALUES (
        v_bt_run_id,
        v_org_id,
        NULL,  -- customer_id is null for public back-tests
        NOW(),
        'running'  -- Valid status: 'running', 'ok', or 'error'
    );
    
    -- 2. Create back-test parameters (includes date range)
    -- NOTE: We do NOT set b1-b11 (CI band trade size percentages) here.
    -- ef_bt_execute will automatically apply its defaultBands when b1-b11 are null/zero:
    -- B1=0.22796, B2=0.21397, B3=0.19943, B4=0.18088, B5=0.12229, 
    -- B6=0.00157, B7=0.002, B8=0.00441, B9=0.01287, B10=0.033, B11=0.09572
    -- These percentages work with actual CryptoQuant price levels from lth_pvr.ci_bands_daily
    INSERT INTO lth_pvr_bt.bt_params (
        bt_run_id,
        start_date,
        end_date,
        upfront_contrib_usdt,
        monthly_contrib_usdt,
        maker_bps_trade,
        maker_bps_contrib,
        performance_fee_pct,
        platform_fee_pct,
        momo_len,
        momo_thr,
        enable_retrace
    ) VALUES (
        v_bt_run_id,
        p_start_date,
        p_end_date,
        p_upfront_usdt,
        p_monthly_usdt,
        8.0,     -- 8 bps (0.08%) VALR exchange fee for BTC/USDT trades (charged in BTC)
        18.0,    -- 18 bps (0.18%) VALR exchange fee for USDT/ZAR trades (charged in USDT)
        0.10,    -- 10% (0.10) BitWealth performance fee (high-water mark)
        0.0075,  -- 0.75% (0.0075) BitWealth platform fee on contributions
        5,       -- 5-day momentum length (matching Admin UI default)
        0.00,    -- 0% momentum threshold (matching Admin UI default)
        false    -- Disable retrace logic (matching Admin UI default)
    );
    
    -- 3. NOW create request record (references bt_run_id via FK)
    INSERT INTO public.backtest_requests (
        email,
        request_date,
        start_date,
        end_date,
        upfront_usdt,
        monthly_usdt,
        status,
        bt_run_id
    ) VALUES (
        p_email,
        CURRENT_DATE,
        p_start_date,
        p_end_date,
        p_upfront_usdt,
        p_monthly_usdt,
        'running',
        v_bt_run_id
    ) RETURNING id INTO v_request_id;
    
    -- Get remaining requests
    v_remaining := public.get_remaining_backtest_requests(p_email);
    
    -- Return success with IDs for polling
    RETURN json_build_object(
        'success', true,
        'request_id', v_request_id,
        'bt_run_id', v_bt_run_id,
        'remaining', v_remaining,
        'message', 'Back-test queued successfully'
    );
    
EXCEPTION
    WHEN OTHERS THEN
        RETURN json_build_object(
            'success', false,
            'error', 'Internal error: ' || SQLERRM
        );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.run_public_backtest(p_email text, p_captcha_token text, p_start_date date, p_end_date date, p_upfront_usdt numeric, p_monthly_usdt numeric)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_request_id UUID;
    v_bt_run_id UUID;
    v_remaining INTEGER;
    v_org_id UUID;
    v_captcha_valid BOOLEAN;
    v_captcha_response JSON;
BEGIN
  PERFORM public.assert_org_admin();
    -- 1. Verify CAPTCHA token with Google reCAPTCHA API
    BEGIN
        SELECT content::json INTO v_captcha_response
        FROM http((
            'POST',
            'https://www.google.com/recaptcha/api/siteverify',
            ARRAY[http_header('Content-Type', 'application/x-www-form-urlencoded')],
            'application/x-www-form-urlencoded',
            'secret=' || current_setting('app.settings.recaptcha_secret_key', true) || 
            '&response=' || p_captcha_token
        ));
        
        v_captcha_valid := COALESCE((v_captcha_response->>'success')::boolean, false);
    EXCEPTION WHEN OTHERS THEN
        -- If reCAPTCHA API call fails, log error but don't block (fallback to rate limiting only)
        v_captcha_valid := true;
        RAISE WARNING 'reCAPTCHA verification failed: %', SQLERRM;
    END;
    
    IF NOT v_captcha_valid THEN
        RETURN json_build_object(
            'success', false,
            'error', 'CAPTCHA verification failed. Please try again.'
        );
    END IF;
    
    -- 2. Validate email format
    IF p_email !~ '^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$' THEN
        RETURN json_build_object(
            'success', false,
            'error', 'Invalid email format'
        );
    END IF;
    
    -- 3. Check rate limit
    IF NOT public.check_backtest_rate_limit(p_email) THEN
        RETURN json_build_object(
            'success', false,
            'error', 'Rate limit exceeded. Maximum 10 back-tests per day per email.',
            'remaining', 0
        );
    END IF;
    
    -- 4. Validate date range
    IF p_start_date >= p_end_date THEN
        RETURN json_build_object(
            'success', false,
            'error', 'End date must be after start date'
        );
    END IF;
    
    IF p_end_date > CURRENT_DATE THEN
        RETURN json_build_object(
            'success', false,
            'error', 'End date cannot be in the future'
        );
    END IF;
    
    -- 5. Validate amounts
    IF p_upfront_usdt < 0 OR p_monthly_usdt < 0 THEN
        RETURN json_build_object(
            'success', false,
            'error', 'Investment amounts must be positive'
        );
    END IF;
    
    IF p_upfront_usdt = 0 AND p_monthly_usdt = 0 THEN
        RETURN json_build_object(
            'success', false,
            'error', 'At least one investment amount must be greater than zero'
        );
    END IF;
    
    -- 6. Get org_id from environment (assuming single org for public back-tests)
    v_org_id := current_setting('app.org_id', true)::UUID;
    IF v_org_id IS NULL THEN
        -- Fallback: get first org (for public back-tests)
        SELECT id INTO v_org_id FROM public.organizations LIMIT 1;
    END IF;
    
    -- 7. Create backtest request record
    INSERT INTO public.backtest_requests (
        email,
        start_date,
        end_date,
        upfront_usdt,
        monthly_usdt,
        status
    ) VALUES (
        LOWER(TRIM(p_email)),
        p_start_date,
        p_end_date,
        p_upfront_usdt,
        p_monthly_usdt,
        'pending'
    ) RETURNING id INTO v_request_id;
    
    -- 8. Create back-test run record in lth_pvr_bt schema
    INSERT INTO lth_pvr_bt.bt_runs (
        org_id,
        status
    ) VALUES (
        v_org_id,
        'running'
    ) RETURNING bt_run_id INTO v_bt_run_id;
    
    -- 9. Link request to bt_run
    UPDATE public.backtest_requests
    SET bt_run_id = v_bt_run_id,
        status = 'running',
        updated_at = NOW()
    WHERE id = v_request_id;
    
    -- 10. Create bt_params record
    -- NOTE: B1-B11 are NULL here, ef_bt_execute will apply Progressive defaults:
    -- B1=0.22796, B2=0.21397, B3=0.19943, B4=0.18088, B5=0.12229, 
    -- B6=0.00157, B7=0.002, B8=0.00441, B9=0.01287, B10=0.033, B11=0.09572
    INSERT INTO lth_pvr_bt.bt_params (
        bt_run_id,
        start_date,
        end_date,
        upfront_contrib_usdt,
        monthly_contrib_usdt,
        maker_bps_trade,
        maker_bps_contrib,
        performance_fee_pct,
        platform_fee_pct,
        momo_len,
        momo_thr,
        enable_retrace
    ) VALUES (
        v_bt_run_id,
        p_start_date,
        p_end_date,
        p_upfront_usdt,
        p_monthly_usdt,
        8.0,   -- VALR maker fee for BTC/USDT trades (0.08%, charged in BTC)
        18.0,  -- VALR deposit fee for USDT/ZAR conversion (0.18%, charged in USDT)
        0.10,  -- 10% BitWealth performance fee (high-water mark)
        0.0075, -- 0.75% BitWealth platform fee on contributions
        5,     -- 5-day momentum length (matching Progressive variation)
        0.00,  -- 0% momentum threshold (matching Progressive variation)
        true   -- Enable retrace logic (matching Progressive variation default)
    );
    
    -- 11. Get remaining count
    v_remaining := public.get_remaining_backtest_requests(p_email);
    
    -- 12. Return success with request_id
    RETURN json_build_object(
        'success', true,
        'request_id', v_request_id,
        'remaining', v_remaining,
        'message', 'Back-test queued successfully. Results will be available shortly.'
    );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.set_customer_fee_plan(p_customer_id bigint, p_fee_plan text, p_created_by text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_current text; v_eff date; v_org uuid;
        v_plat numeric; v_plat_s text; v_mgmt numeric; v_mgmt_s text; v_perf numeric; v_perf_s text;
BEGIN
  PERFORM public.assert_org_admin();
  IF p_fee_plan NOT IN ('platform','management') THEN
    RETURN jsonb_build_object('success',false,'error','fee_plan must be platform or management'); END IF;
  SELECT org_id, fee_plan, platform_fee_rate, platform_fee_schedule, management_fee_rate, management_fee_schedule,
         performance_fee_rate, performance_fee_schedule
    INTO v_org, v_current, v_plat, v_plat_s, v_mgmt, v_mgmt_s, v_perf, v_perf_s
    FROM public.customer_strategies WHERE customer_id=p_customer_id AND strategy_code IN ('LTH_PVR','STH_CB') LIMIT 1;
  IF NOT FOUND THEN RETURN jsonb_build_object('success',false,'error','Customer strategy not found'); END IF;
  IF v_current = p_fee_plan THEN
    RETURN jsonb_build_object('success',true,'no_change',true,'message','Already on '||p_fee_plan||' plan'); END IF;

  v_eff := (date_trunc('month', CURRENT_DATE) + interval '1 month')::date;
  UPDATE public.customer_fee_plan_history SET effective_to = v_eff - 1
   WHERE customer_id=p_customer_id AND strategy_code IN ('LTH_PVR','STH_CB') AND effective_to IS NULL AND effective_from < v_eff;
  INSERT INTO public.customer_fee_plan_history(
    org_id, customer_id, strategy_code, fee_plan, platform_fee_rate, platform_fee_schedule,
    management_fee_rate, management_fee_schedule, performance_fee_rate, performance_fee_schedule,
    effective_from, effective_to, created_by, note)
  VALUES(v_org, p_customer_id, 'LTH_PVR', p_fee_plan, v_plat, v_plat_s, v_mgmt, v_mgmt_s, v_perf, v_perf_s,
    v_eff, NULL, p_created_by, 'Plan switch '||v_current||' -> '||p_fee_plan||' effective '||v_eff);
  RETURN jsonb_build_object('success',true,'customer_id',p_customer_id,'previous_plan',v_current,
    'new_plan',p_fee_plan,'effective_from',v_eff,'message','Plan switch scheduled for '||v_eff);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.sth_cb_bt_get_annual(p_bt_run_id uuid)
 RETURNS SETOF sth_cb_bt.v_bt_results_annual
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$

BEGIN
  PERFORM public.assert_org_admin();

  PERFORM sth_cb_bt.assert_run_access(p_bt_run_id);

  RETURN QUERY SELECT * FROM sth_cb_bt.v_bt_results_annual v

