CREATE OR REPLACE FUNCTION public.sth_cb_bt_get_run(p_bt_run_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$

DECLARE v jsonb;

BEGIN
  PERFORM public.assert_org_admin();

  PERFORM sth_cb_bt.assert_run_access(p_bt_run_id);

  SELECT jsonb_build_object('run', to_jsonb(r), 'params', to_jsonb(p))

    INTO v

  FROM sth_cb_bt.bt_runs r

  LEFT JOIN sth_cb_bt.bt_params p ON p.bt_run_id = r.bt_run_id

  WHERE r.bt_run_id = p_bt_run_id;

  RETURN v;

END $function$
;
CREATE OR REPLACE FUNCTION public.sth_cb_bt_get_std_dca_balances(p_bt_run_id uuid)
 RETURNS SETOF sth_cb_bt.bt_std_dca_balances
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$

BEGIN
  PERFORM public.assert_org_admin();

  PERFORM sth_cb_bt.assert_run_access(p_bt_run_id);

  RETURN QUERY SELECT * FROM sth_cb_bt.bt_std_dca_balances d

               WHERE d.bt_run_id = p_bt_run_id ORDER BY d.trade_date;

END $function$
;
CREATE OR REPLACE FUNCTION public.ta_bot_candles(p_org_id uuid, p_exchange text, p_symbol text, p_timeframe text, p_limit integer DEFAULT 1500)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'ta_bot'
AS $function$
BEGIN
  PERFORM public.assert_org_admin();
  PERFORM public.ta_bot_assert_admin(p_org_id);
  RETURN COALESCE((
    SELECT jsonb_agg(jsonb_build_object(
             'time', extract(epoch FROM open_time)::bigint,
             'open', open, 'high', high, 'low', low, 'close', close, 'volume', volume)
           ORDER BY open_time)
    FROM (
      SELECT * FROM ta_bot.candles
      WHERE exchange = p_exchange AND symbol = p_symbol AND timeframe = p_timeframe AND confirmed
      ORDER BY open_time DESC LIMIT LEAST(GREATEST(p_limit, 1), 5000)
    ) c), '[]'::jsonb);
END $function$
;
CREATE OR REPLACE FUNCTION public.ta_bot_instruments(p_org_id uuid, p_search text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'ta_bot'
AS $function$
BEGIN
  PERFORM public.assert_org_admin();
  PERFORM public.ta_bot_assert_admin(p_org_id);
  RETURN jsonb_build_object(
    'tracked', COALESCE((
      SELECT jsonb_agg(jsonb_build_object('exchange', exchange, 'symbol', symbol, 'tv_symbol', tv_symbol,
                                          'tick_size', tick_size, 'status', status) ORDER BY symbol)
      FROM ta_bot.instruments WHERE tracked), '[]'::jsonb),
    'matches', CASE WHEN p_search IS NULL OR length(p_search) < 2 THEN '[]'::jsonb ELSE COALESCE((
      SELECT jsonb_agg(jsonb_build_object('exchange', exchange, 'symbol', symbol, 'tv_symbol', tv_symbol,
                                          'tracked', tracked, 'status', status) ORDER BY symbol)
      FROM (SELECT * FROM ta_bot.instruments
             WHERE status = 'Trading' AND (symbol ILIKE upper(p_search) || '%' OR tv_symbol ILIKE '%' || p_search || '%')
             ORDER BY symbol LIMIT 30) m), '[]'::jsonb) END);
END $function$
;
CREATE OR REPLACE FUNCTION public.ta_bot_latest_analysis(p_org_id uuid, p_exchange text, p_symbol text, p_style text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'ta_bot'
AS $function$
DECLARE v_run ta_bot.analysis_runs%ROWTYPE;
BEGIN
  PERFORM public.assert_org_admin();
  PERFORM public.ta_bot_assert_admin(p_org_id);
  SELECT * INTO v_run FROM ta_bot.analysis_runs
   WHERE exchange = p_exchange AND symbol = p_symbol AND style = p_style AND status = 'ok'
   ORDER BY started_at DESC LIMIT 1;
  IF NOT FOUND THEN RETURN NULL; END IF;

  RETURN jsonb_build_object(
    'run', jsonb_build_object(
      'run_id', v_run.run_id, 'started_at', v_run.started_at, 'finished_at', v_run.finished_at,
      'candles_through', v_run.candles_through, 'timeframes', to_jsonb(v_run.timeframes),
      'tool_codes', to_jsonb(v_run.tool_codes), 'meta', v_run.meta),
    'zones', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'zone_id', zone_id, 'price_low', price_low, 'price_high', price_high, 'bias', bias,
        'score', score, 'prob_baseline', prob_baseline, 'prob_final', prob_final,
        'tool_codes', to_jsonb(tool_codes), 'rationale', rationale, 'expires_at', expires_at)
        ORDER BY score DESC)
      FROM ta_bot.confluence_zones WHERE run_id = v_run.run_id), '[]'::jsonb),
    'levels', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'level_id', level_id, 'timeframe', timeframe, 'tool_code', tool_code, 'level_type', level_type,
        'price_low', price_low, 'price_high', price_high, 'strength', strength, 'meta', meta)
        ORDER BY price_low)
      FROM ta_bot.levels WHERE run_id = v_run.run_id), '[]'::jsonb));
END $function$
;
CREATE OR REPLACE FUNCTION public.ta_bot_set_tracked(p_org_id uuid, p_exchange text, p_symbol text, p_tracked boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'ta_bot'
AS $function$
DECLARE v_n int;
BEGIN
  PERFORM public.assert_org_admin();
  PERFORM public.ta_bot_assert_admin(p_org_id);
  UPDATE ta_bot.instruments SET tracked = p_tracked, updated_at = now()
   WHERE exchange = p_exchange AND symbol = p_symbol;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN jsonb_build_object('updated', v_n);
END $function$
;
CREATE OR REPLACE FUNCTION public.ta_bot_status(p_org_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'ta_bot'
AS $function$
BEGIN
  PERFORM public.assert_org_admin();
  PERFORM public.ta_bot_assert_admin(p_org_id);
  RETURN jsonb_build_object(
    'workers', COALESCE((SELECT jsonb_agg(to_jsonb(w) ORDER BY last_seen_at DESC) FROM ta_bot.worker_heartbeat w), '[]'::jsonb),
    'tools', COALESCE((SELECT jsonb_agg(jsonb_build_object('tool_code', tool_code, 'name', name, 'version', version,
                        'enabled', enabled, 'weight', weight, 'params', params) ORDER BY tool_code) FROM ta_bot.tools), '[]'::jsonb),
    'recent_runs', COALESCE((
      SELECT jsonb_agg(jsonb_build_object('symbol', symbol, 'style', style, 'status', status,
                        'started_at', started_at, 'zones', (meta->>'zoneCount')::int) ORDER BY started_at DESC)
      FROM (SELECT * FROM ta_bot.analysis_runs ORDER BY started_at DESC LIMIT 20) r), '[]'::jsonb),
    'coverage', COALESCE((
      SELECT jsonb_agg(jsonb_build_object('symbol', symbol, 'timeframe', timeframe, 'n', n, 'last_ts', last_ts) ORDER BY symbol, timeframe)
      FROM (SELECT symbol, timeframe, count(*) n, max(open_time) last_ts FROM ta_bot.candles WHERE confirmed GROUP BY 1,2) c), '[]'::jsonb));
END $function$
;
CREATE OR REPLACE FUNCTION public.update_customer_fee_rate(p_customer_id bigint, p_new_fee_rate numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  PERFORM public.assert_org_admin();
  RETURN public.update_customer_fee_rates(p_customer_id, p_new_fee_rate, NULL);
END;
$function$
;
CREATE OR REPLACE FUNCTION public.update_customer_fee_rates(p_customer_id bigint, p_performance_fee_rate numeric DEFAULT NULL::numeric, p_platform_fee_rate numeric DEFAULT NULL::numeric, p_performance_fee_schedule text DEFAULT NULL::text, p_platform_fee_schedule text DEFAULT NULL::text, p_management_fee_rate numeric DEFAULT NULL::numeric, p_management_fee_schedule text DEFAULT NULL::text, p_created_by text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'lth_pvr'
AS $function$
DECLARE
  v_org uuid; v_found boolean;
  cur_perf numeric; cur_plat numeric; cur_mgmt numeric;
  cur_perf_s text; cur_plat_s text; cur_mgmt_s text;
BEGIN
  PERFORM public.assert_org_admin();
  IF p_performance_fee_rate IS NOT NULL AND (p_performance_fee_rate<0 OR p_performance_fee_rate>1) THEN
    RETURN jsonb_build_object('success',false,'error','Performance fee rate must be between 0 and 1'); END IF;
  IF p_platform_fee_rate IS NOT NULL AND (p_platform_fee_rate<0 OR p_platform_fee_rate>1) THEN
    RETURN jsonb_build_object('success',false,'error','Platform fee rate must be between 0 and 1'); END IF;
  IF p_management_fee_rate IS NOT NULL AND (p_management_fee_rate<0 OR p_management_fee_rate>1) THEN
    RETURN jsonb_build_object('success',false,'error','Management fee rate must be between 0 and 1'); END IF;
  IF p_performance_fee_schedule IS NOT NULL AND p_performance_fee_schedule NOT IN ('monthly','quarterly','annual') THEN
    RETURN jsonb_build_object('success',false,'error','Performance fee schedule invalid'); END IF;
  IF p_platform_fee_schedule IS NOT NULL AND p_platform_fee_schedule NOT IN ('immediate','monthly','quarterly','annual') THEN
    RETURN jsonb_build_object('success',false,'error','Platform fee schedule invalid'); END IF;
  IF p_management_fee_schedule IS NOT NULL AND p_management_fee_schedule NOT IN ('monthly','quarterly','annual') THEN
    RETURN jsonb_build_object('success',false,'error','Management fee schedule invalid'); END IF;

  SELECT org_id INTO v_org FROM public.customer_details WHERE customer_id=p_customer_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('success',false,'error','Customer not found'); END IF;

  SELECT performance_fee_rate, platform_fee_rate, management_fee_rate,
         performance_fee_schedule, platform_fee_schedule, management_fee_schedule
    INTO cur_perf, cur_plat, cur_mgmt, cur_perf_s, cur_plat_s, cur_mgmt_s
    FROM public.customer_strategies WHERE customer_id=p_customer_id AND strategy_code IN ('LTH_PVR','STH_CB') LIMIT 1;
  IF NOT FOUND THEN RETURN jsonb_build_object('success',false,'error','Customer strategy not found'); END IF;

  UPDATE public.customer_strategies SET
    performance_fee_rate     = COALESCE(p_performance_fee_rate, performance_fee_rate),
    platform_fee_rate        = COALESCE(p_platform_fee_rate, platform_fee_rate),
    performance_fee_schedule = COALESCE(p_performance_fee_schedule, performance_fee_schedule),
    platform_fee_schedule    = COALESCE(p_platform_fee_schedule, platform_fee_schedule),
    management_fee_rate      = COALESCE(p_management_fee_rate, management_fee_rate),
    management_fee_schedule  = COALESCE(p_management_fee_schedule, management_fee_schedule)
  WHERE customer_id=p_customer_id AND strategy_code IN ('LTH_PVR','STH_CB');

  PERFORM public.fn_write_fee_history(p_customer_id, CURRENT_DATE, p_created_by, 'Rate/schedule update');

  RETURN jsonb_build_object(
    'success', true,
    'customer_id', p_customer_id,
    'previous_performance_fee_rate', COALESCE(cur_perf, 0.10),
    'previous_platform_fee_rate', COALESCE(cur_plat, 0.0075),
    'previous_management_fee_rate', COALESCE(cur_mgmt, 0.01),
    'new_performance_fee_rate', COALESCE(p_performance_fee_rate, cur_perf, 0.10),
    'new_platform_fee_rate', COALESCE(p_platform_fee_rate, cur_plat, 0.0075),
    'new_management_fee_rate', COALESCE(p_management_fee_rate, cur_mgmt, 0.01),
    'previous_performance_fee_schedule', COALESCE(cur_perf_s, 'monthly'),
    'previous_platform_fee_schedule', COALESCE(cur_plat_s, 'immediate'),
    'previous_management_fee_schedule', COALESCE(cur_mgmt_s, 'monthly'),
    'new_performance_fee_schedule', COALESCE(p_performance_fee_schedule, cur_perf_s, 'monthly'),
    'new_platform_fee_schedule', COALESCE(p_platform_fee_schedule, cur_plat_s, 'immediate'),
    'new_management_fee_schedule', COALESCE(p_management_fee_schedule, cur_mgmt_s, 'monthly'),
    'message', 'Fee rates updated'
  );
END;
$function$
;
CREATE OR REPLACE FUNCTION public.upsert_entity_director(p_customer_id bigint, p_data jsonb, p_related_person_id bigint DEFAULT NULL::bigint)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id  bigint;
  v_org uuid;
BEGIN
  PERFORM public.assert_org_admin();
  SELECT org_id INTO v_org FROM public.customer_details WHERE customer_id = p_customer_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Customer % not found', p_customer_id; END IF;

  IF p_related_person_id IS NULL THEN
    INSERT INTO public.client_related_persons (customer_id, org_id, role)
    VALUES (p_customer_id, v_org, COALESCE(p_data->>'role','director'))
    RETURNING related_person_id INTO v_id;
  ELSE
    v_id := p_related_person_id;
  END IF;

  UPDATE public.client_related_persons SET
    role                = COALESCE(p_data->>'role', role),
    is_authorized_rep   = COALESCE((p_data->>'is_authorized_rep')::boolean, is_authorized_rep),
    can_login           = COALESCE((p_data->>'can_login')::boolean, can_login),
    shareholding_pct    = COALESCE((p_data->>'shareholding_pct')::numeric, shareholding_pct),
    title               = COALESCE(p_data->>'title', title),
    first_names         = COALESCE(p_data->>'first_names', first_names),
    last_name           = COALESCE(p_data->>'last_name', last_name),
    id_type             = COALESCE(p_data->>'id_type', id_type),
    id_number           = COALESCE(p_data->>'id_number', id_number),
    id_passport_number  = COALESCE(p_data->>'id_passport_number', id_passport_number),
    date_of_birth       = COALESCE((p_data->>'date_of_birth')::date, date_of_birth),
    gender              = COALESCE(p_data->>'gender', gender),
    nationality         = COALESCE(p_data->>'nationality', nationality),
    country_of_residence= COALESCE(p_data->>'country_of_residence', country_of_residence),
    email               = COALESCE(p_data->>'email', email),
    phone_country_code  = COALESCE(p_data->>'phone_country_code', phone_country_code),
    phone_number        = COALESCE(p_data->>'phone_number', phone_number),
    occupation          = COALESCE(p_data->>'occupation', occupation),
    tax_number          = COALESCE(p_data->>'tax_number', tax_number),
    source_of_funds     = COALESCE(p_data->>'source_of_funds', source_of_funds),
    source_of_income    = COALESCE(p_data->>'source_of_income', source_of_income),
    source_of_wealth    = COALESCE(p_data->>'source_of_wealth', source_of_wealth),
    address_line1       = COALESCE(p_data->>'address_line1', address_line1),
    address_line2       = COALESCE(p_data->>'address_line2', address_line2),
    address_line3       = COALESCE(p_data->>'address_line3', address_line3),
    city                = COALESCE(p_data->>'city', city),
    province            = COALESCE(p_data->>'province', province),
    postal_code         = COALESCE(p_data->>'postal_code', postal_code),
    country             = COALESCE(p_data->>'country', country),
    updated_at          = now()
  WHERE related_person_id = v_id;

  RETURN v_id;
END;
$function$
;
commit;
